SELECT app_name, SUM(ppl_cnt) AS user_count
FROM {table_name}
GROUP BY app_name
ORDER BY user_count DESC
LIMIT 10;

SELECT
  ROUND(
    100.0 * SUM(CASE WHEN gender = '女' THEN ppl_cnt ELSE 0 END)
    / NULLIF(SUM(CASE WHEN gender IN ('男', '女') THEN ppl_cnt ELSE 0 END), 0),
    2
  ) AS female_percent
FROM {table_name}
WHERE gender IN ('男', '女');

SELECT app_name, SUM(ppl_cnt) AS user_count
FROM {table_name}
WHERE 1 = 0
GROUP BY app_name
ORDER BY user_count DESC
LIMIT 1;

SELECT
  gender,
  ROUND(
    {population_base}.0 * SUM(ppl_cnt)
    / NULLIF((
      SELECT SUM(ppl_cnt)
      FROM {table_name}
      WHERE gender IN ('男', '女')
    ), 0)
  ) AS estimated_user_count
FROM {table_name}
WHERE category = '社交沟通'
  AND gender IN ('男', '女')
GROUP BY gender
ORDER BY estimated_user_count DESC;
